-- Schéma public relevé en production le 28 octobre 2026 (tables bilan_*, contraintes, index, RLS, politiques, droits).
create table public.bilan_reponses (bilan_id uuid not null, question_id text not null, valeur text[] not null, texte_libre jsonb, source text default 'declare'::text not null, answered_at timestamp with time zone default now() not null);
create table public.bilan_missions (id text not null, question_id text, parcours text, titre text not null, duree_min integer not null, methode text, critere_fin text, etapes jsonb default '[]'::jsonb not null, ressources jsonb default '[]'::jsonb not null, prerequis text[] default '{}'::text[] not null, declenche_sur text[] default '{B,C}'::text[] not null, disponible boolean default false not null, updated_at timestamp with time zone default now() not null, comprendre jsonb);
create table public.bilan_mission_suivi (bilan_id uuid not null, mission_id text not null, statut text default 'en_cours'::text not null, etapes_faites integer[] default '{}'::integer[] not null, note text, reporte_jusqu date, termine_at timestamp with time zone, updated_at timestamp with time zone default now() not null);
create table public.bilan_agent_appels (id bigint generated by default as identity not null, member_id uuid not null, agent text not null, tokens_in integer, tokens_out integer, created_at timestamp with time zone default now() not null);
create table public.bilan_bilans (id uuid default gen_random_uuid() not null, member_id uuid default auth.uid() not null, statut text default 'en_cours'::text not null, site_url text, google_nom text, version_regles text default '2026-10-v1'::text not null, created_at timestamp with time zone default now() not null, updated_at timestamp with time zone default now() not null);
create table public.bilan_constats (id uuid default gen_random_uuid() not null, analyse_id uuid not null, bilan_id uuid not null, question_id text not null, proposition text not null, constat text not null, preuve text, source_url text, statut text default 'propose'::text not null, created_at timestamp with time zone default now() not null);
create table public.bilan_question_options (question_id text not null, code text not null, libelle text not null, points integer, ordre integer default 0 not null, mission_id text, condition text, gravite text);
create table public.bilan_plans (id uuid default gen_random_uuid() not null, bilan_id uuid not null, version_regles text not null, etats jsonb not null, restitution text, temps_hebdo text, created_at timestamp with time zone default now() not null, analyse_detaillee jsonb);
create table public.bilan_contenus (id uuid default gen_random_uuid() not null, member_id uuid not null, agent text default 'studio-instagram'::text not null, mission_id text, format text not null, persona_index integer, persona_prenom text, brief jsonb default '{}'::jsonb not null, resultat jsonb not null, favori boolean default false not null, created_at timestamp with time zone default now() not null);
create table public.bilan_inscriptions (evenement_id uuid not null, member_id uuid default auth.uid() not null, created_at timestamp with time zone default now() not null);
create table public.bilan_studio_contenu (member_id uuid not null, persona_pro jsonb, piliers jsonb default '{}'::jsonb not null, idees jsonb default '{}'::jsonb not null, sujets_utilises jsonb default '[]'::jsonb not null, updated_at timestamp with time zone default now() not null);
create table public.bilan_evenements (id uuid default gen_random_uuid() not null, titre text not null, theme text, description text, intervenante text, debut timestamp with time zone not null, duree_min integer default 60 not null, zoom_url text, replay_ressource_id text, acces text default 'audit'::text not null, actif boolean default true not null, created_at timestamp with time zone default now() not null);
create table public.bilan_ressources (id text not null, type text not null, theme text not null, titre text not null, description text, format text default 'pdf'::text not null, pages integer, url text not null, acces text default 'tous'::text not null, missions text[] default '{}'::text[] not null, ordre integer default 0 not null, actif boolean default true not null, updated_at timestamp with time zone default now() not null, date_publication date);
create table public.bilan_identite (member_id uuid default auth.uid() not null, reponses jsonb default '{}'::jsonb not null, carte jsonb, statut text default 'en_cours'::text not null, carte_generee_at timestamp with time zone, valide_at timestamp with time zone, updated_at timestamp with time zone default now() not null, portrait jsonb);
create table public.bilan_identite_questions (id text not null, bloc text not null, bloc_titre text not null, bloc_intro text, ordre integer not null, texte text not null, type text not null, options jsonb default '[]'::jsonb not null, aide text, max integer, pourquoi text, active boolean default true not null, condition text, sous_bloc text, options_seance jsonb);
create table public.bilan_textes (member_id uuid default auth.uid() not null, cle text not null, texte text not null, source text, valide_at timestamp with time zone, updated_at timestamp with time zone default now() not null);
create table public.bilan_analyses (id uuid default gen_random_uuid() not null, bilan_id uuid not null, url text not null, statut text default 'en_cours'::text not null, pages jsonb default '[]'::jsonb not null, erreur text, modele text, tokens_in integer, tokens_out integer, created_at timestamp with time zone default now() not null, finished_at timestamp with time zone, audit jsonb);
create table public.bilan_questions (id text not null, kind text not null, parcours text, ordre integer default 0 not null, texte text not null, aide text, dimension text, condition text, multi boolean default false not null, verifiable text, active boolean default true not null, version integer default 1 not null, updated_at timestamp with time zone default now() not null, type text default 'unique'::text not null, seuils jsonb, repere text);
create table public.bilan_plan_missions (plan_id uuid not null, mission_id text not null, ordre integer not null, niveau integer not null, raisons text[] default '{}'::text[] not null, statut text default 'a_faire'::text not null, note text, updated_at timestamp with time zone default now() not null);
create table public.bilan_parcours (code text not null, titre text not null, description text, ordre integer not null);
